import yfinance as yf; T=[x.strip() for x in open("stocks.txt",encoding="utf-8") if x.strip()]; D=yf.download(T,period="3mo",progress=False,auto_adjust=True); C=D["Close"]; V=D["Volume"]; R=sorted([(t,(40 if (p:=float(C[t].dropna().iloc[-2]))>(m:=float(C[t].dropna().iloc[-21:-1].mean())) else 0)+(30 if 3<((p/float(C[t].dropna().iloc[-7])-1)*100)<8 else 0)+(30 if (float(V[t].dropna().iloc[-2])/float(V[t].dropna().iloc[-22:-2].mean()))>=1.5 else 0)+(20 if 50<=(100-(100/(1+(C[t].dropna().diff().iloc[-15:-1].clip(lower=0).mean()/(-C[t].dropna().diff().iloc[-15:-1].clip(upper=0).mean())))))<=65 else 0)) for t in T if t in C.columns and C[t].dropna().shape[0]>=22],key=lambda x:x[1],reverse=True); print("TOP OPPORTUNITES\n"+"\n".join([f"{i+1}. {x[0]} | Confiance {x[1]}/120" for i,x in enumerate(R[:10])]))
